schema_ddl:
CREATE TABLE dipendenti (
    id SERIAL PRIMARY KEY,
    nome TEXT NOT NULL,
    cognome TEXT NOT NULL,
    data_nascita DATE CHECK (data_nascita <= CURRENT_DATE),
    data_assunzione DATE NOT NULL,
    stipendio NUMERIC(10,2) CHECK (stipendio >= 0),
    ruolo TEXT
);

CREATE INDEX idx_dipendenti_stipendio ON dipendenti(stipendio DESC);
